const isRecord = (value) => typeof value === 'object' && value !== null && !Array.isArray(value);
export const parsePackageJsonDependencies = (content) => {
    let parsed;
    try {
        parsed = JSON.parse(content);
    }
    catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        return { packageNames: new Set(), error: `is not valid JSON: ${message}` };
    }
    if (!isRecord(parsed))
        return { packageNames: new Set(), error: 'is not a JSON object' };
    const { dependencies } = parsed;
    return { packageNames: new Set(isRecord(dependencies) ? Object.keys(dependencies) : []) };
};
